import pandas as pd

EXPECTED_COLUMNS = {'date', 'entity_id', 'metric_value', 'unit', 'currency'}
EXPECTED_UNIT = 'count'
EXPECTED_CURRENCY = 'INR'

def validate_ingest(df: pd.DataFrame) -> None:
    missing_cols = EXPECTED_COLUMNS - set(df.columns)
    if missing_cols:
        raise ValueError(f'Schema drift detected, missing columns: {missing_cols}')

    unexpected_units = set(df['unit'].unique()) - {EXPECTED_UNIT}
    if unexpected_units:
        raise ValueError(f'Unexpected unit values, check for a vendor methodology change: {unexpected_units}')

    unexpected_currency = set(df['currency'].unique()) - {EXPECTED_CURRENCY}
    if unexpected_currency:
        raise ValueError(f'Unexpected currency values, check for a vendor format change: {unexpected_currency}')

    if df['metric_value'].isna().mean() > 0.05:
        raise ValueError('More than 5% of values are missing, investigate before this reaches a signal')

# Run this on every new file or API pull, before it ever reaches
# feature engineering. A loud failure here is far cheaper than a
# silently corrupted signal three steps downstream.
